    "    p[\"pos\"] : save\n"
    "    return parse_assign_no_semi(p)\n"
    "\n"
    "def parse_assign_no_semi(p):\n"
    "    x : peek(p)\n"
    "    left : parse_expr(p)\n"
    "    tt : peek(p)[\"text\"]\n"
    "    if tt = \"=\":\n"
    "        take(p)\n"
    "        val : parse_expr(p)\n"
    "        z : node(\"Assign\", x)\n"
    "        z[\"target\"] : left\n"
    "        z[\"value\"] : val\n"
    "        validate_target(p, left)\n"
    "        return z\n"
    "    if tt in [\"+=\", \"-=\", \"*=\", \"/=\"]:\n"
    "        op : take(p)[\"text\"]\n"
    "        z : node(\"AugAssign\", x)\n"
    "        z[\"target\"] : left\n"
    "        validate_target(p, left)\n"
    "        z[\"op\"] : op\n"
    "        z[\"value\"] : parse_expr(p)\n"
    "        return z\n"
    "    if tt = \"++\" or tt = \"--\":\n"
    "        take(p)\n"
    "        z : node(\"AugAssign\", x)\n"
    "        z[\"target\"] : left\n"
    "        validate_target(p, left)\n"
    "        z[\"op\"] : \"+=\" if tt = \"++\" else \"-=\"\n"
    "        one : node(\"Const\", x)\n"
    "        one[\"value\"] : \"1\"\n"
    "        one[\"kind\"] : \"number\"\n"
    "        z[\"value\"] : one\n"
    "        return z\n"
    "    z : node(\"Expr\", x)\n"
    "    z[\"value\"] : left\n"
    "    return z\n"
    "\n"
    "def parse_expr_stmt(p):\n"
    "    z : parse_assign_no_semi(p)\n"
    "    need(p, \";\")\n"
    "    return z\n"
    "\n"
    "def validate_target(p, x):\n"
    "    if x[\"t\"] = \"Name\" or x[\"t\"] = \"Attr\" or x[\"t\"] = \"Subscript\":\n"
    "        return\n"
    "    fail(p, \"unsupported assignment target\", x)\n"
    "\n"
    "def is_lambda_ahead(p):\n"
    "    if kind(p, \"NAME\") and not is_kw(peek(p)[\"text\"]) and peekn(p, 1)[\"text\"] = \"=>\":\n"
    "        return True\n"
    "    if peek(p)[\"text\"] = \"(\":\n"
    "        depth : 0\n"
    "        j : 0\n"
    "        while True:\n"
    "            t : peekn(p, j)\n"
    "            if t[\"kind\"] = \"END\":\n"
    "                return False\n"
    "            tx : t[\"text\"]\n"
    "            if tx = \"(\":\n"
    "                depth += 1\n"
    "            elif tx = \")\":\n"
    "                depth += -1\n"
    "                if depth = 0:\n"
    "                    return peekn(p, j + 1)[\"text\"] = \"=>\"\n"
    "            j += 1\n"
    "    return False\n"
    "\n"
    "def parse_expr(p):\n"
    "    if is_lambda_ahead(p):\n"
    "        return parse_lambda(p)\n"
    "    return parse_ternary(p)\n"
    "\n"
    "def parse_lambda_param(p):\n"
    "    if kind(p, \"NAME\") and peekn(p, 1)[\"kind\"] = \"NAME\":\n"
    "        skip_type(p)\n"
    "    a : need_kind(p, \"NAME\")\n"
    "    return ident(p, a)\n"
    "\n"
    "def parse_lambda(p):\n"
    "    x : peek(p)\n"
    "    args : []\n"
    "    if at(p, \"(\"):\n"
    "        take(p)\n"
    "        if not at(p, \")\"):\n"
    "            while True:\n"
    "                args.append(parse_lambda_param(p))\n"
    "                if not at(p, \",\"):\n"
    "                    break\n"
    "                take(p)\n"
    "        need(p, \")\")\n"
    "    else:\n"
    "        a : need_kind(p, \"NAME\")\n"
    "        args.append(ident(p, a))\n"
    "    need(p, \"=>\")\n"
    "    if at(p, \"{\"):\n"
    "        fail(p, \"block-bodied lambdas are unsupported\", peek(p))\n"
    "    if len(args) > 1:\n"
    "        fail(p, \"multi-argument lambdas are unsupported\", x)\n"
    "    z : node(\"Lambda\", x)\n"
    "    z[\"args\"] : args\n"
    "    z[\"body\"] : parse_expr(p)\n"
    "    return z\n"
    "\n"
    "def parse_ternary(p):\n"
    "    c : parse_or(p)\n"
    "    if at(p, \"?\"):\n"
    "        take(p)\n"
    "        a : parse_expr(p)\n"
    "        need(p, \":\")\n"
    "        b : parse_expr(p)\n"
    "        z : node(\"IfExp\", c)\n"
    "        z[\"body\"] : a\n"
    "        z[\"test\"] : c\n"
    "        z[\"orelse\"] : b\n"
    "        return z\n"
    "    return c\n"
    "\n"
    "def parse_or(p):\n"
    "    xs : [parse_and(p)]\n"
    "    x : xs[0]\n"
    "    while at(p, \"||\"):\n"
    "        take(p)\n"
    "        xs.append(parse_and(p))\n"
    "    if len(xs) = 1:\n"
    "        return x\n"
    "    z : node(\"BoolOp\", x)\n"
    "    z[\"op\"] : \"or\"\n"
    "    z[\"values\"] : xs\n"
    "    return z\n"
    "\n"
    "def parse_and(p):\n"
    "    xs : [parse_compare(p)]\n"
    "    x : xs[0]\n"
    "    while at(p, \"&&\"):\n"
    "        take(p)\n"
    "        xs.append(parse_compare(p))\n"
    "    if len(xs) = 1:\n"
    "        return x\n"
    "    z : node(\"BoolOp\", x)\n"
    "    z[\"op\"] : \"and\"\n"
    "    z[\"values\"] : xs\n"
    "    return z\n"
    "\n"
    "def parse_compare(p):\n"
    "    left : parse_add(p)\n"
    "    if peek(p)[\"text\"] in [\"==\", \"!=\", \"<\", \"<=\", \">\", \">=\"]:\n"
    "        op : take(p)[\"text\"]\n"
    "        right : parse_add(p)\n"
    "        z : node(\"Compare\", left)\n"
    "        z[\"left\"] : left\n"
    "        z[\"op\"] : op\n"
    "        z[\"right\"] : right\n"
    "        return z\n"
    "    return left\n"
    "\n"
    "def parse_add(p):\n"
    "    z : parse_mul(p)\n"
    "    while peek(p)[\"text\"] = \"+\" or peek(p)[\"text\"] = \"-\":\n"
    "        op : take(p)[\"text\"]\n"
    "        q : node(\"BinOp\", z)\n"
    "        q[\"left\"] : z\n"
    "        q[\"op\"] : op\n"
    "        q[\"right\"] : parse_mul(p)\n"
    "        z : q\n"
    "    return z\n"
    "\n"
    "def parse_mul(p):\n"
    "    z : parse_unary(p)\n"
    "    while peek(p)[\"text\"] in [\"*\", \"/\", \"%\"]:\n"
    "        op : take(p)[\"text\"]\n"
    "        q : node(\"BinOp\", z)\n"
    "        q[\"left\"] : z\n"
    "        q[\"op\"] : op\n"
    "        q[\"right\"] : parse_unary(p)\n"
    "        z : q\n"
    "    return z\n"
    "\n"
    "def parse_unary(p):\n"
    "    tt : peek(p)[\"text\"]\n"
    "    if tt = \"!\":\n"
    "        x : take(p)\n"
    "        z : node(\"Unary\", x)\n"
    "        z[\"op\"] : \"not\"\n"
    "        z[\"value\"] : parse_unary(p)\n"
    "        return z\n"
    "    if tt = \"-\":\n"
    "        x : take(p)\n"
    "        z : node(\"Unary\", x)\n"
    "        z[\"op\"] : \"-\"\n"
    "        z[\"value\"] : parse_unary(p)\n"
    "        return z\n"
    "    if tt = \"+\":\n"
    "        fail(p, \"unary plus is unsupported\", peek(p))\n"
    "    if tt = \"++\" or tt = \"--\":\n"
    "        fail(p, \"prefix increment is unsupported\", peek(p))\n"
    "    return parse_postfix(p)\n"
    "\n"
    "def parse_postfix(p):\n"
    "    z : parse_atom(p)\n"
    "    while True:\n"
    "        if at(p, \".\"):\n"
    "            x : take(p)\n"
    "            a : need_kind(p, \"NAME\")\n"
    "            q : node(\"Attr\", x)\n"
    "            q[\"value\"] : z\n"
    "            q[\"attr\"] : a[\"text\"]\n"
    "            z : q\n"
    "        elif at(p, \"(\"):\n"
    "            x : take(p)\n"
    "            q : node(\"Call\", x)\n"
    "            q[\"func\"] : z\n"
    "            q[\"args\"] : []\n"
    "            q[\"kwargs\"] : []\n"
    "            if not at(p, \")\"):\n"
    "                while True:\n"
    "                    if kind(p, \"NAME\") and peekn(p, 1)[\"text\"] = \":\":\n"
    "                        k : take(p)\n"
    "                        ident(p, k)\n"
    "                        take(p)\n"
    "                        q[\"kwargs\"].append([k, parse_expr(p)])\n"
    "                    else:\n"
    "                        q[\"args\"].append(parse_expr(p))\n"
    "                    if not at(p, \",\"):\n"
    "                        break\n"
    "                    take(p)\n"
    "            need(p, \")\")\n"
    "            z : q\n"
    "        elif at(p, \"[\"):\n"
    "            x : take(p)\n"
    "            q : node(\"Subscript\", x)\n"
    "            q[\"value\"] : z\n"
    "            q[\"slice\"] : parse_index(p)\n"
    "            need(p, \"]\")\n"
    "            z : q\n"
    "        else:\n"
    "            break\n"
    "    return z\n"
    "\n"
    "def parse_index(p):\n"
    "    x : peek(p)\n"
    "    lower : None\n"
    "    if not at(p, \"..\") and not at(p, \"]\"):\n"
    "        lower : parse_expr(p)\n"
    "    if at(p, \"..\"):\n"
    "        take(p)\n"
    "        z : node(\"Slice\", x)\n"
    "        z[\"lower\"] : lower\n"
    "        z[\"upper\"] : None\n"
    "        z[\"step\"] : None\n"
    "        if not at(p, \"]\"):\n"
    "            z[\"upper\"] : parse_expr(p)\n"
    "        return z\n"
    "    return lower\n"
    "\n"
    "def parse_new(p):\n"
    "    x : take(p)\n"
    "    if at(p, \"{\"):\n"
    "        return parse_anon_object(p, x)\n"
    "    if at(p, \"[\"):\n"
    "        take(p)\n"
    "        need(p, \"]\")\n"
    "        return parse_array_init(p, x)\n"
    "    if kind(p, \"NAME\"):\n"
    "        tn : take(p)[\"text\"]\n"
    "        if at(p, \"<\"):\n"
    "            skip_generics(p)\n"
    "        if at(p, \"[\"):\n"
    "            take(p)\n"
    "            if at(p, \"]\"):\n"
    "                take(p)\n"
    "                return parse_array_init(p, x)\n"
    "            fail(p, \"sized array 'new \" + tn + \"[N]' is unsupported\", x)\n"
    "        if at(p, \"(\"):\n"
    "            take(p)\n"
    "            if not at(p, \")\"):\n"
    "                depth : 1\n"
    "                while depth > 0 and not kind(p, \"END\"):\n"
    "                    tt : peek(p)[\"text\"]\n"
    "                    if tt = \"(\":\n"
    "                        depth += 1\n"
    "                    elif tt = \")\":\n"
    "                        depth += -1\n"
    "                    take(p)\n"
    "            else:\n"
    "                take(p)\n"
    "        if at(p, \"{\"):\n"
    "            if is_dict_type(tn):\n"
    "                return parse_dict_init(p, x)\n"
    "            return parse_array_init(p, x)\n"
    "        fail(p, \"unsupported 'new \" + tn + \"' expression\", x)\n"
    "    fail(p, \"unsupported 'new' expression\", x)\n"
    "\n"
    "def is_dict_type(tn):\n"
    "    return tn = \"Dictionary\" or tn = \"SortedDictionary\" or tn = \"IDictionary\"\n"
    "\n"
    "def parse_anon_object(p, x):\n"
    "    need(p, \"{\")\n"
    "    z : node(\"Dict\", x)\n"
    "    z[\"keys\"] : []\n"
    "    z[\"values\"] : []\n"
    "    if not at(p, \"}\"):\n"
    "        while True:\n"
    "            nm : need_kind(p, \"NAME\")\n"
    "            need(p, \"=\")\n"
    "            v : parse_expr(p)\n"
    "            k : node(\"Const\", nm)\n"
    "            k[\"value\"] : nm[\"text\"]\n"
    "            k[\"kind\"] : \"string\"\n"
    "            z[\"keys\"].append(k)\n"
    "            z[\"values\"].append(v)\n"
    "            if not at(p, \",\"):\n"
    "                break\n"
    "            take(p)\n"
    "            if at(p, \"}\"):\n"
    "                break\n"
    "    need(p, \"}\")\n"
    "    return z\n"
    "\n"
    "def parse_dict_init(p, x):\n"
    "    need(p, \"{\")\n"
    "    z : node(\"Dict\", x)\n"
    "    z[\"keys\"] : []\n"
    "    z[\"values\"] : []\n"
    "    if not at(p, \"}\"):\n"
    "        while True:\n"
    "            need(p, \"{\")\n"
    "            k : parse_expr(p)\n"
    "            need(p, \",\")\n"
    "            v : parse_expr(p)\n"
    "            need(p, \"}\")\n"
    "            z[\"keys\"].append(k)\n"
    "            z[\"values\"].append(v)\n"
    "            if not at(p, \",\"):\n"
    "                break\n"
    "            take(p)\n"
    "            if at(p, \"}\"):\n"
    "                break\n"
    "    need(p, \"}\")\n"
    "    return z\n"
    "\n"
    "def parse_array_init(p, x):\n"
    "    need(p, \"{\")\n"
    "    z : node(\"List\", x)\n"
    "    z[\"elts\"] : []\n"
    "    if not at(p, \"}\"):\n"
    "        while True:\n"
    "            z[\"elts\"].append(parse_expr(p))\n"
    "            if not at(p, \",\"):\n"
    "                break\n"
    "            take(p)\n"
    "            if at(p, \"}\"):\n"
    "                break\n"
    "    need(p, \"}\")\n"
    "    return z\n"
    "\n"
    "def parse_atom(p):\n"
    "    x : peek(p)\n"
    "    if kind(p, \"NUMBER\"):\n"
    "        take(p)\n"
    "        z : node(\"Const\", x)\n"
    "        z[\"value\"] : x[\"text\"]\n"
    "        z[\"kind\"] : \"number\"\n"
    "        return z\n"
    "    if kind(p, \"STRING\"):\n"
    "        take(p)\n"
    "        if x[\"val\"][\"f\"]:\n"
    "            depth : 0\n"
    "            j : 0\n"
    "            sv : x[\"val\"][\"s\"]\n"
    "            while j < len(sv):\n"
    "                c : sv[j]\n"
    "                if c = \"{\":\n"
    "                    if j + 1 < len(sv) and sv[j + 1] = \"{\":\n"
    "                        j += 2\n"
    "                        continue\n"
    "                    depth += 1\n"
    "                elif c = \"}\":\n"
    "                    depth += -1\n"
    "                elif depth > 0 and (c = \"!\" or c = \":\"):\n"
    "                    fail(p, \"interpolation conversions/format specs are unsupported\", x)\n"
    "                j += 1\n"
    "            z : node(\"FString\", x)\n"
    "            z[\"value\"] : sv\n"
    "            z[\"kind\"] : \"string\"\n"
    "            return z\n"
    "        z : node(\"Const\", x)\n"
    "        z[\"value\"] : x[\"val\"][\"s\"]\n"
    "        z[\"kind\"] : \"string\"\n"
    "        return z\n"
    "    if at(p, \"true\") or at(p, \"false\") or at(p, \"null\"):\n"
    "        take(p)\n"
    "        z : node(\"Const\", x)\n"
    "        z[\"value\"] : \"True\" if x[\"text\"] = \"true\" else (\"False\" if x[\"text\"] = \"false\" else \"None\")\n"
    "        z[\"kind\"] : \"number\"\n"
    "        return z\n"
    "    if at(p, \"new\"):\n"
    "        return parse_new(p)\n"
    "    if kind(p, \"NAME\"):\n"
    "        take(p)\n"
    "        if is_kw(x[\"text\"]):\n"
    "            fail(p, \"unexpected keyword '\" + x[\"text\"] + \"'\", x)\n"
    "        z : node(\"Name\", x)\n"
    "        z[\"value\"] : ident(p, x)\n"
    "        x[\"text\"] : z[\"value\"]\n"
    "        return z\n"
    "    if at(p, \"(\"):\n"
    "        take(p)\n"
    "        z : parse_expr(p)\n"
    "        need(p, \")\")\n"
    "        return z\n"
    "    fail(p, \"unsupported expression\", x)\n"
    "\n"
    "def pad(n):\n"
    "    return \"    \" * n\n"
    "\n"
    "def render(ast, state):\n"
    "    state[\"comments\"] : ast[\"comments\"]\n"
    "    state[\"inline\"] : ast[\"inline\"]\n"
    "    state[\"last_comment\"] : 0\n"
    "    state[\"filename\"] : ast[\"filename\"]\n"
    "    lines : render_body(ast[\"body\"], state, 0, True)\n"
    "    for k in state[\"comments\"].keys():\n"
    "        kn : int(k)\n"
    "        if kn > state[\"last_comment\"]:\n"
    "            lines.append(state[\"comments\"][k])\n"
    "    text : \"\"\n"
    "    for line in lines:\n"
    "        if line != \"\":\n"
    "            text += line + \"\\n\"\n"
    "    return text\n"
    "\n"
    "def before_comments(st, line, indent):\n"
    "    out : []\n"
    "    for k in st[\"comments\"].keys():\n"
    "        kn : int(k)\n"
    "        if kn > st[\"last_comment\"] and kn < line:\n"
    "            out.append(pad(indent) + st[\"comments\"][k])\n"
    "            st[\"last_comment\"] : kn\n"
    "    return out\n"
    "\n"
    "def render_body(body, st, indent, doc_ok):\n"
    "    out : []\n"
    "    i : 0\n"
    "    while i < len(body):\n"
    "        s : body[i]\n"
    "        cs : before_comments(st, s[\"line\"], indent)\n"
    "        for c in cs:\n"
    "            out.append(c)\n"
    "        rs : render_stmt(s, st, indent)\n"
    "        key : str(s[\"line\"])\n"
    "        if key in st[\"inline\"] and len(rs) > 0:\n"
    "            rs[0] : rs[0] + \"  \" + st[\"inline\"][key]\n"
    "        for q in rs:\n"
    "            if q != \"\":\n"
    "                out.append(q)\n"
    "        i += 1\n"
    "    return out\n"
    "\n"
    "def render_stmt(s, st, ind):\n"
    "    p : pad(ind)\n"
    "    t : s[\"t\"]\n"
    "    if t = \"Seq\":\n"
    "        out : []\n"
    "        for c in s[\"body\"]:\n"
    "            for q in render_stmt(c, st, ind):\n"
    "                out.append(q)\n"
    "        return out\n"
    "    if t = \"Assign\":\n"
    "        return [p + target_text(s[\"target\"], st) + \" : \" + expr_text(s[\"value\"], st)]\n"
    "    if t = \"AugAssign\":\n"
    "        return [p + target_text(s[\"target\"], st) + \" \" + s[\"op\"] + \" \" + expr_text(s[\"value\"], st)]\n"
    "    if t = \"Return\":\n"
    "        return [p + (\"return\" if s[\"value\"] = None else \"return \" + expr_text(s[\"value\"], st))]\n"
    "    if t = \"break\" or t = \"continue\" or t = \"pass\":\n"
    "        return [p + t]\n"
    "    if t = \"Import\":\n"
    "        return [\"\" if s[\"erase\"] else p + \"import \" + s[\"name\"]]\n"
    "    if t = \"Expr\":\n"
    "        return [p + expr_text(s[\"value\"], st)]\n"
    "    if t = \"FunctionDef\":\n"
    "        out : []\n"
    "        for d in s[\"decorators\"]:\n"
    "            out.append(p + \"@\" + expr_text(d, st))\n"
    "        parts : []\n"
    "        i : 0\n"
    "        while i < len(s[\"args\"]):\n"
    "            q : s[\"args\"][i]\n"
    "            if s[\"defaults\"][i] != None:\n"
    "                q += \":\" + expr_text(s[\"defaults\"][i], st)\n"
    "            parts.append(q)\n"
    "            i += 1\n"
    "        out.append(p + \"def \" + s[\"name\"] + \"(\" + join_text(parts, \", \") + \"):\")\n"
    "        for q in render_body(s[\"body\"], st, ind + 1, True):\n"
    "            out.append(q)\n"
    "        return out\n"
    "    if t = \"If\":\n"
    "        out : [p + \"if \" + expr_text(s[\"test\"], st) + \":\"]\n"
    "        for q in render_body(s[\"body\"], st, ind + 1, False):\n"
    "            out.append(q)\n"
    "        for e in s[\"elifs\"]:\n"
    "            out.append(p + \"elif \" + expr_text(e[\"test\"], st) + \":\")\n"
    "            for q in render_body(e[\"body\"], st, ind + 1, False):\n"
    "                out.append(q)\n"
    "        if len(s[\"orelse\"]) > 0:\n"
    "            out.append(p + \"else:\")\n"
    "            for q in render_body(s[\"orelse\"], st, ind + 1, False):\n"
    "                out.append(q)\n"
    "        return out\n"
    "    if t = \"While\":\n"
    "        out : [p + \"while \" + expr_text(s[\"test\"], st) + \":\"]\n"
    "        for q in render_body(s[\"body\"], st, ind + 1, False):\n"
    "            out.append(q)\n"
    "        return out\n"
    "    if t = \"For\":\n"
    "        out : [p + \"for \" + target_text(s[\"target\"], st) + \" in \" + expr_text(s[\"iter\"], st) + \":\"]\n"
    "        for q in render_body(s[\"body\"], st, ind + 1, False):\n"
    "            out.append(q)\n"
    "        return out\n"
    "    return []\n"
    "\n"
    "def join_text(xs, sep):\n"
    "    out : \"\"\n"
    "    i : 0\n"
    "    while i < len(xs):\n"
    "        if i > 0:\n"
    "            out += sep\n"
    "        out += xs[i]\n"
    "        i += 1\n"
    "    return out\n"
    "\n"
    "def target_text(x, st):\n"
    "    if x[\"t\"] = \"Tuple\" or x[\"t\"] = \"List\":\n"
    "        parts : []\n"
    "        for e in x[\"elts\"]:\n"
    "            parts.append(target_text(e, st))\n"
    "        return join_text(parts, \", \")\n"
    "    return expr_text(x, st)\n"
    "\n"
    "def slice_text(x, st):\n"
    "    if x[\"t\"] = \"Slice\":\n"
    "        a : \"\" if x[\"lower\"] = None else expr_text(x[\"lower\"], st)\n"
    "        b : \"\" if x[\"upper\"] = None else expr_text(x[\"upper\"], st)\n"
    "        q : a + \":\" + b\n"
    "        if x[\"step\"] != None:\n"
    "            q += \":\" + expr_text(x[\"step\"], st)\n"
    "        return q\n"
    "    return expr_text(x, st)\n"
    "\n"
    "def expr_text(x, st):\n"
    "    t : x[\"t\"]\n"
    "    if t = \"Name\":\n"
    "        return x[\"value\"]\n"
    "    if t = \"Const\":\n"
    "        if x[\"kind\"] = \"string\":\n"
    "            return quote_string(x[\"value\"])\n"
    "        return x[\"value\"]\n"
    "    if t = \"FString\":\n"
    "        return \"f\" + quote_string(x[\"value\"])\n"
    "    if t = \"List\":\n"
    "        parts : []\n"
    "        for e in x[\"elts\"]:\n"
    "            parts.append(expr_text(e, st))\n"
    "        return \"[\" + join_text(parts, \", \") + \"]\"\n"
    "    if t = \"Tuple\":\n"
    "        parts : []\n"
    "        for e in x[\"elts\"]:\n"
    "            parts.append(expr_text(e, st))\n"
    "        if len(parts) = 1:\n"
    "            return \"(\" + parts[0] + \",)\"\n"
    "        return \"(\" + join_text(parts, \", \") + \")\"\n"
    "    if t = \"Dict\":\n"
    "        parts : []\n"
    "        i : 0\n"
    "        while i < len(x[\"keys\"]):\n"
    "            parts.append(expr_text(x[\"keys\"][i], st) + \": \" + expr_text(x[\"values\"][i], st))\n"
    "            i += 1\n"
    "        return \"{\" + join_text(parts, \", \") + \"}\"\n"
    "    if t = \"Attr\":\n"
    "        if x[\"value\"][\"t\"] = \"Name\" and x[\"value\"][\"value\"] in st[\"aliases\"]:\n"
    "            raise st[\"filename\"] + \":\" + str(x[\"line\"]) + \":\" + str(x[\"col\"]) + \": \" + st[\"aliases\"][x[\"value\"][\"value\"]] + \".\" + x[\"attr\"] + \" is unsupported outside a mapped call\"\n"
    "        if x[\"attr\"] = \"Length\" or x[\"attr\"] = \"Count\":\n"
    "            return \"len(\" + expr_text(x[\"value\"], st) + \")\"\n"
    "        return expr_text(x[\"value\"], st) + \".\" + x[\"attr\"]\n"
    "    if t = \"Subscript\":\n"
    "        return expr_text(x[\"value\"], st) + \"[\" + slice_text(x[\"slice\"], st) + \"]\"\n"
    "    if t = \"Unary\":\n"
    "        return \"(\" + (\"not \" if x[\"op\"] = \"not\" else \"-\") + expr_text(x[\"value\"], st) + \")\"\n"
    "    if t = \"BinOp\":\n"
    "        return \"(\" + expr_text(x[\"left\"], st) + \" \" + x[\"op\"] + \" \" + expr_text(x[\"right\"], st) + \")\"\n"
    "    if t = \"BoolOp\":\n"
    "        parts : []\n"
    "        for e in x[\"values\"]:\n"
    "            parts.append(expr_text(e, st))\n"
    "        return \"(\" + join_text(parts, \" \" + x[\"op\"] + \" \") + \")\"\n"
    "    if t = \"Compare\":\n"
    "        op : \"=\" if x[\"op\"] = \"==\" else x[\"op\"]\n"
    "        return \"(\" + expr_text(x[\"left\"], st) + \" \" + op + \" \" + expr_text(x[\"right\"], st) + \")\"\n"
    "    if t = \"IfExp\":\n"
    "        return expr_text(x[\"body\"], st) + \" if \" + expr_text(x[\"test\"], st) + \" else \" + expr_text(x[\"orelse\"], st)\n"
    "    if t = \"Lambda\":\n"
    "        return \"(lambda \" + join_text(x[\"args\"], \", \") + \": \" + expr_text(x[\"body\"], st) + \")\"\n"
    "    if t = \"Call\":\n"
    "        lowered : lower_call(x, st)\n"
    "        if lowered != None:\n"
    "            return lowered\n"
    "        parts : []\n"
    "        for e in x[\"args\"]:\n"
    "            parts.append(expr_text(e, st))\n"
    "        for kv in x[\"kwargs\"]:\n"
    "            parts.append(kv[0][\"text\"] + \":\" + expr_text(kv[1], st))\n"
    "        return expr_text(x[\"func\"], st) + \"(\" + join_text(parts, \", \") + \")\"\n"
    "    return \"\"\n"
    "\n"
    "def lower_call(x, st):\n"
    "    f : x[\"func\"]\n"
    "    if f[\"t\"] = \"Attr\" and f[\"value\"][\"t\"] = \"Name\" and f[\"value\"][\"value\"] = \"Console\":\n"
    "        if f[\"attr\"] = \"WriteLine\" or f[\"attr\"] = \"Write\":\n"
    "            parts : []\n"
    "            for e in x[\"args\"]:\n"
    "                parts.append(expr_text(e, st))\n"
    "            return \"print(\" + join_text(parts, \", \") + \")\"\n"
    "        raise st[\"filename\"] + \":\" + str(x[\"line\"]) + \":\" + str(x[\"col\"]) + \": Console.\" + f[\"attr\"] + \" is unsupported\"\n"
    "    if f[\"t\"] != \"Attr\" or f[\"value\"][\"t\"] != \"Name\":\n"
    "        return None\n"
    "    alias : f[\"value\"][\"value\"]\n"
    "    if not alias in st[\"aliases\"]:\n"
    "        return None\n"
    "    mod : st[\"aliases\"][alias]\n"
    "    name : f[\"attr\"]\n"
    "    if mod = \"numpy\":\n"
    "        if name = \"Array\" or name = \"AsArray\":\n"
    "            if len(x[\"args\"]) != 1 or len(x[\"kwargs\"]) != 0:\n"
    "                raise st[\"filename\"] + \":\" + str(x[\"line\"]) + \":\" + str(x[\"col\"]) + \": Np.\" + name + \" requires one argument\"\n"
    "            return expr_text(x[\"args\"][0], st)\n"
    "        maps : {\"Sum\":\"sum\", \"Mean\":\"avg\", \"Min\":\"min\", \"Max\":\"max\", \"Dot\":\"dot\",\n"
    "                \"Matmul\":\"mmul\", \"Abs\":\"abs\", \"Sqrt\":\"sqrt\", \"Exp\":\"exp\", \"Log\":\"log\",\n"
    "                \"Sin\":\"sin\", \"Cos\":\"cos\", \"Tan\":\"tan\"}\n"
    "        if not name in maps:\n"
    "            raise st[\"filename\"] + \":\" + str(x[\"line\"]) + \":\" + str(x[\"col\"]) + \": Np.\" + name + \" is unsupported\"\n"
    "        if len(x[\"kwargs\"]) > 0:\n"
    "            raise st[\"filename\"] + \":\" + str(x[\"line\"]) + \":\" + str(x[\"col\"]) + \": Np.\" + name + \" options are unsupported\"\n"
    "        parts : []\n"
    "        for e in x[\"args\"]:\n"
    "            parts.append(expr_text(e, st))\n"
    "        return maps[name] + \"(\" + join_text(parts, \", \") + \")\"\n"
    "    if mod = \"pandas\":\n"
    "        if name = \"Series\":\n"
    "            if len(x[\"args\"]) != 1 or len(x[\"kwargs\"]) != 0:\n"
    "                raise st[\"filename\"] + \":\" + str(x[\"line\"]) + \":\" + str(x[\"col\"]) + \": Pd.Series requires one argument\"\n"
    "            return expr_text(x[\"args\"][0], st)\n"
    "        if name != \"DataFrame\":\n"
    "            raise st[\"filename\"] + \":\" + str(x[\"line\"]) + \":\" + str(x[\"col\"]) + \": Pd.\" + name + \" is unsupported\"\n"
    "        if len(x[\"args\"]) != 1 or len(x[\"kwargs\"]) != 0 or x[\"args\"][0][\"t\"] != \"Dict\":\n"
    "            raise st[\"filename\"] + \":\" + str(x[\"line\"]) + \":\" + str(x[\"col\"]) + \": Pd.DataFrame requires one anonymous object or dictionary argument\"\n"
    "        d : x[\"args\"][0]\n"
    "        parts : []\n"
    "        i : 0\n"
    "        while i < len(d[\"keys\"]):\n"
    "            k : d[\"keys\"][i]\n"
    "            if k[\"t\"] != \"Const\" or k[\"kind\"] != \"string\" or not re_match(\"^[A-Za-z_][A-Za-z0-9_]*$\", k[\"value\"]):\n"
    "                raise st[\"filename\"] + \":\" + str(k[\"line\"]) + \":\" + str(k[\"col\"]) + \": DataFrame column names must be valid identifiers\"\n"
    "            parts.append(k[\"value\"] + \":\" + expr_text(d[\"values\"][i], st))\n"
    "            i += 1\n"
    "        return \"table(\" + join_text(parts, \", \") + \")\"\n"
    "    return None\n"
    "\n"
    "def transpile(source, filename):\n"
    "    ast : parse(source, filename)\n"
    "    return render(ast, {\"aliases\":ast[\"aliases\"]})\n"
    "\n"
    "def main():\n"
    "    return transpile_cli.run(argv, \"cs2s.ie\", \"cs\", transpile)\n"
    "\n"
    "# Run CLI only when this file is the entry script.\n"
    "if re_match(\"cs2s\\\\.ie$\", argv[0]):\n"
    "    main()\n"
;
#endif /* SHAKTI_SHAKTI_CS2S_SOURCE_H */
